<script lang="ts">
import { authClient } from '$lib/auth-client';
let email=$state('');let busy=$state(false);let message=$state('');let success=$state(false);
async function submit(e:SubmitEvent){e.preventDefault();busy=true;message='';try{const result=await authClient.requestPasswordReset({email,redirectTo:`${location.origin}/reset-password`});if(result.error){success=false;message='Unable to process reset request. Check the email delivery configuration.';}else{success=true;message='If your email exists, you will receive a reset link.';}}catch{message='Unable to request reset. Try again later.';}finally{busy=false;}}
</script><svelte:head><title>Forgot password · Kid Postgres</title></svelte:head><main class="auth-wrap"><form class="auth-card" onsubmit={submit}><a href="/sign-in" class="text-sm text-violet-300">← Back to sign in</a><h1 class="text-3xl font-bold mt-6">Forgot password?</h1><p class="text-slate-400 mt-2">We'll send a reset link if this account exists.</p>{#if message}<p role="status" class:success class:alert={!success} class="mt-5">{message}</p>{/if}<label class="label" for="email">Email</label><input id="email" class="field" type="email" bind:value={email} required/><button class="primary w-full mt-6" disabled={busy}>{busy?'Sending...':'Request reset link'}</button></form></main>
